            while pivot_row < m and A[pivot_row][i] == 0:
                pivot_row += 1
            if pivot_row == m:
                continue
            A[i], A[pivot_row] = A[pivot_row], A[i]
        for j in range(m):
            if i != j:
                factor = A[j][i] / A[i][i]
                for k in range(n):
